     9	public class ReportController {
    10	    public static void setup(Javalin app, Database db) {
    11	        ReportService service = new ReportService(db);
    12	
    13	        app.get("/reports/occupancy", ctx -> {
    14	            try {
    15	                String dateStr = ctx.queryParam("date");
    16	                if (dateStr == null || dateStr.isEmpty()) {
    17	                    ctx.status(400).json(Map.of(
    18	                        "error", "INVALID_REQUEST",
    19	                        "message", "Parâmetro 'date' obrigatório"
    20	                    ));
    21	                    return;
    22	                }
    23	
    24	                LocalDate date = LocalDate.parse(dateStr);
    25	                String csv = service.getOccupancyReport(date);
    26	                ctx.contentType("text/csv; charset=utf-8").result(csv);
    27	            } catch (Exception e) {
    28	                ctx.status(400).json(Map.of(
    29	                    "error", "INVALID_REQUEST",
    30	                    "message", "Data em formato inválido"
    31	                ));
    32	            }
    33	        });
    34	
    35	        app.get("/reports/revenue", ctx -> {
    36	            try {
    37	                String monthStr = ctx.queryParam("month");
    38	                if (monthStr == null || monthStr.isEmpty()) {
    39	                    ctx.status(400).json(Map.of(
    40	                        "error", "INVALID_REQUEST",
    41	                        "message", "Parâmetro 'month' obrigatório"
    42	                    ));
    43	                    return;
    44	                }
    45	
    46	                String[] parts = monthStr.split("-");
    47	                if (parts.length != 2) {
    48	                    throw new Exception("Invalid format");
    49	                }
    50	                int year = Integer.parseInt(parts[0]);
    51	                int month = Integer.parseInt(parts[1]);
    52	
    53	                String csv = service.getRevenueReport(year, month);
    54	                ctx.contentType("text/csv; charset=utf-8").result(csv);
    55	            } catch (Exception e) {
    56	                ctx.status(400).json(Map.of(
    57	                    "error", "INVALID_REQUEST",
    58	                    "message", "Mês em formato inválido"
    59	                ));
    60	            }
    61	        });
    62	    }
    63	}
