     1	package com.pousada.api;
     2	
     3	import io.javalin.Javalin;
     4	import com.google.gson.Gson;
     5	import com.google.gson.JsonObject;
     6	import com.pousada.db.Database;
     7	import com.pousada.model.Document;
     8	import com.pousada.model.Reservation;
     9	import com.pousada.service.ReservationService;
    10	import java.time.LocalDate;
    11	import java.util.Map;
    12	
    13	public class ReservationController {
    14	    private static final Gson gson = new Gson();
    15	
    16	    public static void setup(Javalin app, Database db) {
    17	        ReservationService service = new ReservationService(db);
    18	
    19	        app.post("/reservations", ctx -> {
    20	            try {
    21	                JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
    22	
    23	                validateReservationInput(body);
    24	
    25	                int roomNumber = body.get("roomNumber").getAsInt();
    26	                String guestName = body.get("guestName").getAsString();
    27	                String guestEmail = body.get("guestEmail").getAsString();
    28	                LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString());
    29	                LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString());
    30	                int guests = body.get("guests").getAsInt();
    31	                String ratePlan = body.get("ratePlan").getAsString();
    32	
    33	                String guestCpf = body.has("guestCpf") && !body.get("guestCpf").isJsonNull()
    34	                    ? body.get("guestCpf").getAsString() : null;
    35	                String companyCnpj = body.has("companyCnpj") && !body.get("companyCnpj").isJsonNull()
    36	                    ? body.get("companyCnpj").getAsString() : null;
    37	                String companyName = body.has("companyName") && !body.get("companyName").isJsonNull()
    38	                    ? body.get("companyName").getAsString() : null;
    39	                String guestPassport = body.has("guestPassport") && !body.get("guestPassport").isJsonNull()
    40	                    ? body.get("guestPassport").getAsString() : null;
    41	                String guestCountry = body.has("guestCountry") && !body.get("guestCountry").isJsonNull()
    42	                    ? body.get("guestCountry").getAsString() : null;
    43	
    44	                int identificationCount = (guestCpf != null ? 1 : 0) +
    45	                                         ((companyCnpj != null) ? 1 : 0) +
    46	                                         ((guestPassport != null) ? 1 : 0);
    47	
    48	                if (identificationCount != 1) {
    49	                    ctx.status(400).json(Map.of(
    50	                        "error", "INVALID_REQUEST",
    51	                        "message", "Exatamente um tipo de identificação deve ser fornecido"
    52	                    ));
    53	                    return;
    54	                }
    55	
    56	                Reservation res = service.createReservation(roomNumber, guestName, guestEmail,
    57	                        guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
    58	                        checkIn, checkOut, guests, ratePlan);
    59	
    60	                ctx.status(201).json(reservationToJson(res));
    61	            } catch (ReservationService.ValidationException e) {
    62	                handleValidationError(ctx, e);
    63	            } catch (Exception e) {
    64	                ctx.status(400).json(Map.of(
    65	                    "error", "INVALID_REQUEST",
    66	                    "message", e.getMessage()
    67	                ));
    68	            }
    69	        });
    70	
    71	        app.get("/reservations/{id}", ctx -> {
    72	            try {
    73	                long id = Long.parseLong(ctx.pathParam("id"));
    74	                Reservation res = service.getReservation(id);
    75	                ctx.json(reservationToJson(res));
    76	            } catch (ReservationService.ValidationException e) {
    77	                handleValidationError(ctx, e);
    78	            }
    79	        });
    80	
    81	        app.post("/reservations/{id}/confirmation", ctx -> {
    82	            try {
    83	                long id = Long.parseLong(ctx.pathParam("id"));
    84	                Reservation res = service.confirmReservation(id);
    85	                ctx.json(reservationToJson(res));
    86	            } catch (ReservationService.ValidationException e) {
    87	                handleValidationError(ctx, e);
    88	            }
    89	        });
    90	
    91	        app.post("/reservations/{id}/cancellation", ctx -> {
    92	            try {
    93	                long id = Long.parseLong(ctx.pathParam("id"));
    94	                Reservation res = service.cancelReservation(id);
    95	                ctx.json(reservationToJson(res));
    96	            } catch (ReservationService.ValidationException e) {
    97	                handleValidationError(ctx, e);
    98	            }
    99	        });
   100	
   101	        app.post("/reservations/{id}/check-in", ctx -> {
   102	            try {
   103	                long id = Long.parseLong(ctx.pathParam("id"));
   104	                Reservation res = service.checkIn(id);
   105	                ctx.json(reservationToJson(res));
   106	            } catch (ReservationService.ValidationException e) {
   107	                handleValidationError(ctx, e);
   108	            }
   109	        });
   110	
   111	        app.post("/reservations/{id}/check-out", ctx -> {
   112	            try {
   113	                long id = Long.parseLong(ctx.pathParam("id"));
   114	                Document doc = service.checkOut(id);
   115	                ctx.json(documentToJson(doc));
   116	            } catch (ReservationService.ValidationException e) {
   117	                handleValidationError(ctx, e);
   118	            }
   119	        });
   120	
   121	        app.get("/reservations/{id}/document", ctx -> {
   122	            try {
   123	                long id = Long.parseLong(ctx.pathParam("id"));
   124	                Document doc = service.getDocument(id);
   125	                ctx.json(documentToJson(doc));
   126	            } catch (ReservationService.ValidationException e) {
   127	                handleValidationError(ctx, e);
   128	            }
   129	        });
   130	    }
   131	
   132	    private static void validateReservationInput(JsonObject body) throws Exception {
   133	        String[] required = {"roomNumber", "guestName", "guestEmail", "checkIn", "checkOut", "guests", "ratePlan"};
   134	        for (String field : required) {
   135	            if (!body.has(field) || body.get(field).isJsonNull()) {
   136	                throw new Exception("Campo obrigatório faltando: " + field);
   137	            }
   138	        }
   139	    }
   140	
   141	    private static Map<String, Object> reservationToJson(Reservation res) {
   142	        return Map.ofEntries(
   143	            Map.entry("id", res.id),
   144	            Map.entry("roomNumber", res.roomNumber),
   145	            Map.entry("guestName", res.guestName),
   146	            Map.entry("guestEmail", res.guestEmail),
   147	            Map.entry("guestCpf", res.guestCpf),
   148	            Map.entry("companyCnpj", res.companyCnpj),
   149	            Map.entry("companyName", res.companyName),
   150	            Map.entry("guestPassport", res.guestPassport),
   151	            Map.entry("guestCountry", res.guestCountry),
   152	            Map.entry("checkIn", res.checkIn.toString()),
   153	            Map.entry("checkOut", res.checkOut.toString()),
   154	            Map.entry("guests", res.guests),
   155	            Map.entry("ratePlan", res.ratePlan),
   156	            Map.entry("nights", res.nights),
   157	            Map.entry("subtotal", res.subtotal),
   158	            Map.entry("discount", res.discount),
   159	            Map.entry("total", res.total),
   160	            Map.entry("status", res.status),
   161	            Map.entry("amountPaid", res.amountPaid),
   162	            Map.entry("refund", res.refund)
   163	        );
   164	    }
   165	
   166	    private static Map<String, Object> documentToJson(Document doc) {
   167	        return Map.ofEntries(
   168	            Map.entry("title", doc.title),
   169	            Map.entry("reservationId", doc.reservationId),
   170	            Map.entry("guestName", doc.guestName),
   171	            Map.entry("guestCpf", doc.guestCpf),
   172	            Map.entry("companyCnpj", doc.companyCnpj),
   173	            Map.entry("companyName", doc.companyName),
   174	            Map.entry("guestPassport", doc.guestPassport),
   175	            Map.entry("guestCountry", doc.guestCountry),
   176	            Map.entry("roomNumber", doc.roomNumber),
   177	            Map.entry("roomType", doc.roomType),
   178	            Map.entry("checkIn", doc.checkIn.toString()),
   179	            Map.entry("checkOut", doc.checkOut.toString()),
   180	            Map.entry("nights", doc.nights),
   181	            Map.entry("subtotal", doc.subtotal),
   182	            Map.entry("discount", doc.discount),
   183	            Map.entry("total", doc.total),
   184	            Map.entry("text", doc.text)
   185	        );
   186	    }
   187	
   188	    private static void handleValidationError(io.javalin.http.Context ctx, ReservationService.ValidationException e) {
   189	        int status = switch (e.code) {
   190	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
   191	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
   192	            case "CAPACITY_EXCEEDED" -> 422;
   193	            default -> 400;
   194	        };
   195	        ctx.status(status).json(Map.of("error", e.code, "message", e.message));
   196	    }
   197	}
