     1	package com.pousada.db;
     2	
     3	import java.sql.*;
     4	
     5	public class Database {
     6	    private final String url;
     7	    private final String user;
     8	    private final String password;
     9	
    10	    public Database(String url, String user, String password) {
    11	        this.url = url;
    12	        this.user = user;
    13	        this.password = password;
    14	    }
    15	
    16	    public Connection getConnection() throws SQLException {
    17	        return DriverManager.getConnection(url, user, password);
    18	    }
    19	
    20	    public void init() {
    21	        try (Connection conn = getConnection()) {
    22	            String schema = """
    23	                CREATE TABLE IF NOT EXISTS rooms (
    24	                    number INT PRIMARY KEY,
    25	                    type VARCHAR(50) NOT NULL,
    26	                    capacity INT NOT NULL,
    27	                    nightly_rate DECIMAL(10, 2) NOT NULL
    28	                );
    29	
    30	                CREATE TABLE IF NOT EXISTS reservations (
    31	                    id BIGSERIAL PRIMARY KEY,
    32	                    room_number INT NOT NULL,
    33	                    guest_name VARCHAR(255) NOT NULL,
    34	                    guest_email VARCHAR(255) NOT NULL,
    35	                    guest_cpf VARCHAR(14),
    36	                    company_cnpj VARCHAR(18),
    37	                    company_name VARCHAR(255),
    38	                    guest_passport VARCHAR(50),
    39	                    guest_country VARCHAR(100),
    40	                    check_in DATE NOT NULL,
    41	                    check_out DATE NOT NULL,
    42	                    guests INT NOT NULL,
    43	                    rate_plan VARCHAR(50) NOT NULL,
    44	                    nights INT NOT NULL,
    45	                    subtotal DECIMAL(10, 2) NOT NULL,
    46	                    discount DECIMAL(10, 2) NOT NULL DEFAULT 0,
    47	                    total DECIMAL(10, 2) NOT NULL,
    48	                    status VARCHAR(50) NOT NULL,
    49	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    50	                    refund DECIMAL(10, 2),
    51	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    52	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
    53	                );
    54	
    55	                CREATE TABLE IF NOT EXISTS messages (
    56	                    id BIGSERIAL PRIMARY KEY,
    57	                    channel VARCHAR(50) NOT NULL,
    58	                    "to" VARCHAR(255) NOT NULL,
    59	                    subject VARCHAR(255),
    60	                    body TEXT NOT NULL,
    61	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    62	                );
    63	
    64	                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    65	                    (101, 'STANDARD', 2, 249.90),
    66	                    (102, 'STANDARD', 2, 249.90),
    67	                    (201, 'DELUXE', 3, 389.90),
    68	                    (202, 'DELUXE', 3, 389.90),
    69	                    (301, 'SUITE', 4, 579.90)
    70	                ON CONFLICT DO NOTHING;
    71	                """;
    72	
    73	            conn.createStatement().executeUpdate(schema);
    74	        } catch (SQLException e) {
    75	            throw new RuntimeException(e);
    76	        }
    77	    }
    78	}

