   132	    private static void validateReservationInput(JsonObject body) throws Exception {
   133	        String[] required = {"roomNumber", "guestName", "guestEmail", "checkIn", "checkOut", "guests", "ratePlan"};
   134	        for (String field : required) {
   135	            if (!body.has(field) || body.get(field).isJsonNull()) {
