   172	            Map.entry("companyCnpj", doc.companyCnpj),
   173	            Map.entry("companyName", doc.companyName),
   174	            Map.entry("guestPassport", doc.guestPassport),
   175	            Map.entry("guestCountry", doc.guestCountry),
   176	            Map.entry("roomNumber", doc.roomNumber),
   177	            Map.entry("roomType", doc.roomType),
   178	            Map.entry("checkIn", doc.checkIn.toString()),
   179	            Map.entry("checkOut", doc.checkOut.toString()),
   180	            Map.entry("nights", doc.nights),
   181	            Map.entry("subtotal", doc.subtotal),
   182	            Map.entry("discount", doc.discount),
   183	            Map.entry("total", doc.total),
   184	            Map.entry("text", doc.text)
   185	        );
   186	    }
   187	
   188	    private static void handleValidationError(io.javalin.http.Context ctx, ReservationService.ValidationException e) {
   189	        int status = switch (e.code) {
   190	            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
   191	            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
