    13	
    14	public class ReportService {
    15	    private final ReservationRepository reservationRepo;
    16	    private final RoomRepository roomRepo;
    17	
    18	    public ReportService(Database db) {
    19	        this.reservationRepo = new ReservationRepository(db);
    20	        this.roomRepo = new RoomRepository(db);
