    22	
    23	    public String getOccupancyReport(LocalDate date) {
    24	        List<Reservation> reservations = reservationRepo.findByDateForOccupancy(date);
    25	        List<Room> allRooms = roomRepo.findAll();
    26	
    27	        Map<Integer, Reservation> occupancy = new HashMap<>();
    28	        for (Reservation r : reservations) {
    29	            occupancy.put(r.roomNumber, r);
    30	        }
    31	
    32	        StringBuilder csv = new StringBuilder();
    33	        csv.append("room,type,reservation,check_in,check_out\n");
    34	
    35	        for (Room room : allRooms) {
    36	            Reservation res = occupancy.get(room.number);
    37	            if (res != null) {
    38	                csv.append(room.number).append(",")
    39	                   .append(room.type).append(",")
    40	                   .append(res.id).append(",")
    41	                   .append(res.checkIn).append(",")
    42	                   .append(res.checkOut).append("\n");
    43	            }
    44	        }
    45	
    46	        int occupied = occupancy.size();
    47	        int total = allRooms.size();
    48	        csv.append("total,").append(occupied).append("/").append(total);
    49	
    50	        return csv.toString();
    51	    }
    52	
    53	    public String getRevenueReport(int year, int month) {
    54	        List<Reservation> reservations = reservationRepo.findByMonthForRevenue(year, month);
    55	
    56	        StringBuilder csv = new StringBuilder();
    57	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    58	
    59	        BigDecimal total = BigDecimal.ZERO;
    60	        for (Reservation r : reservations) {
    61	            if (!"CANCELLED".equals(r.status) || r.amountPaid.compareTo(BigDecimal.ZERO) > 0) {
    62	                BigDecimal netAmount = r.amountPaid;
    63	                if (r.refund != null) {
    64	                    netAmount = r.amountPaid.subtract(r.refund);
    65	                }
    66	
    67	                csv.append(r.id).append(",")
    68	                   .append(r.roomNumber).append(",")
    69	                   .append(r.checkIn).append(",")
    70	                   .append(r.checkOut).append(",")
    71	                   .append(r.status).append(",")
    72	                   .append(String.format("%.2f", netAmount)).append("\n");
    73	
    74	                total = total.add(netAmount);
    75	            }
    76	        }
    77	
    78	        csv.append("total,,,,").append(String.format("%.2f", total));
    79	
    80	        return csv.toString();
    81	    }
    82	}
