     1	package com.pousada.service;
     2	
     3	import com.pousada.db.Database;
     4	import com.pousada.model.Document;
     5	import com.pousada.model.Reservation;
     6	import com.pousada.model.Room;
     7	import com.pousada.repository.MessageRepository;
     8	import com.pousada.repository.ReservationRepository;
     9	import com.pousada.repository.RoomRepository;
    10	import com.pousada.util.DocumentFormatter;
    11	import com.pousada.util.Pricing;
    12	import java.math.BigDecimal;
    13	import java.time.LocalDate;
    14	import java.util.List;
    15	import java.util.Optional;
    16	
    17	public class ReservationService {
    18	    private final ReservationRepository reservationRepo;
    19	    private final RoomRepository roomRepo;
    20	    private final MessageRepository messageRepo;
    21	
    22	    public ReservationService(Database db) {
    23	        this.reservationRepo = new ReservationRepository(db);
    24	        this.roomRepo = new RoomRepository(db);
    25	        this.messageRepo = new MessageRepository(db);
    26	    }
    27	
    28	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    29	                                        String guestCpf, String companyCnpj, String companyName,
    30	                                        String guestPassport, String guestCountry,
    31	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan)
    32	            throws ValidationException {
    33	
    34	        if (guests < 1) {
    35	            throw new ValidationException("INVALID_REQUEST", "Número de hóspedes deve ser pelo menos 1");
    36	        }
    37	
    38	        Optional<Room> roomOpt = roomRepo.findByNumber(roomNumber);
    39	        if (roomOpt.isEmpty()) {
    40	            throw new ValidationException("ROOM_NOT_FOUND", "Quarto não encontrado");
    41	        }
    42	
    43	        Room room = roomOpt.get();
    44	        if (guests > room.capacity) {
    45	            throw new ValidationException("CAPACITY_EXCEEDED", "Número de hóspedes excede capacidade do quarto");
    46	        }
    47	
    48	        if (!checkOut.isAfter(checkIn)) {
    49	            throw new ValidationException("INVALID_REQUEST", "Data de saída deve ser depois da entrada");
    50	        }
    51	
    52	        List<Reservation> conflicting = reservationRepo.findConflicting(roomNumber, checkIn, checkOut);
    53	        if (!conflicting.isEmpty()) {
    54	            throw new ValidationException("ROOM_UNAVAILABLE", "Quarto não disponível para as datas solicitadas");
    55	        }
    56	
    57	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    58	        BigDecimal nightlyRate = room.nightlyRate;
    59	        BigDecimal subtotal = BigDecimal.ZERO;
    60	
    61	        for (int i = 0; i < nights; i++) {
    62	            LocalDate date = checkIn.plusDays(i);
    63	            BigDecimal dailyRate = Pricing.calculateNightlyRate(nightlyRate, date);
    64	            subtotal = Pricing.calculateSubtotal(dailyRate, 1).add(subtotal);
    65	        }
    66	
    67	        BigDecimal discount = Pricing.calculateDiscount(subtotal, ratePlan);
    68	        BigDecimal total = Pricing.calculateTotal(subtotal, discount);
    69	
    70	        return reservationRepo.create(roomNumber, guestName, guestEmail, guestCpf, companyCnpj, companyName,
    71	                guestPassport, guestCountry, checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
    72	    }
    73	
    74	    public Reservation getReservation(long id) throws ValidationException {
    75	        Optional<Reservation> res = reservationRepo.findById(id);
    76	        if (res.isEmpty()) {
    77	            throw new ValidationException("RESERVATION_NOT_FOUND", "Reserva não encontrada");
    78	        }
    79	        return res.get();
    80	    }
    81	
    82	    public Reservation confirmReservation(long id) throws ValidationException {
    83	        Reservation res = getReservation(id);
    84	        if (!"PENDING".equals(res.status)) {
    85	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Reserva não está pendente");
    86	        }
    87	
    88	        reservationRepo.updateStatus(id, "CONFIRMED");
    89	        reservationRepo.updateAmountPaid(id, res.total);
    90	
    91	        Reservation confirmed = getReservation(id);
    92	
    93	        Document doc = generateDocument(confirmed);
    94	        String emailBody = DocumentFormatter.emailComprovante(confirmed.guestName, doc.text);
    95	        messageRepo.save("EMAIL", confirmed.guestEmail, "Reserva confirmada - Pousada Maré Alta", emailBody);
    96	
    97	        return confirmed;
    98	    }
    99	
   100	    public Reservation checkIn(long id) throws ValidationException {
   101	        Reservation res = getReservation(id);
   102	        if (!"CONFIRMED".equals(res.status)) {
   103	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Reserva não está confirmada");
   104	        }
   105	
   106	        reservationRepo.updateStatus(id, "CHECKED_IN");
   107	        return getReservation(id);
   108	    }
   109	
   110	    public Document checkOut(long id) throws ValidationException {
   111	        Reservation res = getReservation(id);
   112	        if (!"CHECKED_IN".equals(res.status)) {
   113	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Hóspede não fez check-in");
   114	        }
   115	
   116	        reservationRepo.updateStatus(id, "CHECKED_OUT");
   117	        Reservation checkedOut = getReservation(id);
   118	        return generateDocument(checkedOut);
   119	    }
   120	
   121	    public Reservation cancelReservation(long id) throws ValidationException {
   122	        Reservation res = getReservation(id);
   123	
   124	        if (!("PENDING".equals(res.status) || "CONFIRMED".equals(res.status))) {
   125	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Não é possível cancelar esta reserva");
   126	        }
   127	
   128	        BigDecimal refund = BigDecimal.ZERO;
   129	        if ("CONFIRMED".equals(res.status) && "STANDARD".equals(res.ratePlan)) {
   130	            refund = res.amountPaid;
   131	        }
   132	
   133	        reservationRepo.updateStatus(id, "CANCELLED");
   134	        if (refund.compareTo(BigDecimal.ZERO) > 0) {
   135	            reservationRepo.updateRefund(id, refund);
   136	        }
   137	
   138	        return getReservation(id);
   139	    }
   140	
   141	    public Document getDocument(long id) throws ValidationException {
   142	        Reservation res = getReservation(id);
   143	        if (!("CONFIRMED".equals(res.status) || "CHECKED_IN".equals(res.status) || "CHECKED_OUT".equals(res.status))) {
   144	            throw new ValidationException("OPERATION_NOT_ALLOWED", "Documento só disponível para reservas confirmadas");
   145	        }
   146	        return generateDocument(res);
   147	    }
   148	
   149	    private Document generateDocument(Reservation res) throws ValidationException {
   150	        Optional<Room> roomOpt = roomRepo.findByNumber(res.roomNumber);
   151	        if (roomOpt.isEmpty()) {
   152	            throw new ValidationException("ROOM_NOT_FOUND", "Quarto não encontrado");
   153	        }
   154	        Room room = roomOpt.get();
   155	
   156	        String text;
   157	        if (res.guestCpf != null) {
   158	            text = DocumentFormatter.comprovante(res.id, res.guestName, res.guestCpf,
   159	                    res.roomNumber, room.type, res.checkIn, res.checkOut, res.nights,
   160	                    res.subtotal, res.discount, res.total);
   161	        } else if (res.companyCnpj != null) {
   162	            text = DocumentFormatter.fatura(res.id, res.guestName, res.companyCnpj, res.companyName,
   163	                    res.roomNumber, room.type, res.checkIn, res.checkOut, res.nights,
