     1	package com.pousada.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class Pricing {
     8	    private static final BigDecimal PEAK_MULTIPLIER = new BigDecimal("1.20");
     9	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
    10	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
    11	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
    12	
    13	    public static boolean isPeakSeason(LocalDate date) {
    14	        int month = date.getMonthValue();
    15	        int day = date.getDayOfMonth();
    16	
    17	        if (month == 7) return true;
    18	        if (month == 12) return day >= 15;
    19	        if (month == 1 || month == 2) return true;
    20	        return false;
    21	    }
    22	
    23	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    24	        if (isPeakSeason(date)) {
    25	            return baseRate.multiply(PEAK_MULTIPLIER).setScale(2, ROUNDING);
    26	        }
    27	        return baseRate.setScale(2, ROUNDING);
    28	    }
    29	
    30	    public static BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights) {
    31	        return nightlyRate.multiply(new BigDecimal(nights)).setScale(2, ROUNDING);
    32	    }
    33	
    34	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
    35	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    36	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, ROUNDING);
    37	        }
    38	        return BigDecimal.ZERO;
    39	    }
    40	
    41	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    42	        return subtotal.subtract(discount).setScale(2, ROUNDING);
    43	    }
    44	
    45	    public static BigDecimal calculateIss(BigDecimal total) {
    46	        return total.multiply(ISS_RATE).setScale(2, ROUNDING);
    47	    }
    48	}
