     1	package com.pousada;
     2	
     3	import com.pousada.util.Pricing;
     4	import org.junit.Test;
     5	import static org.junit.Assert.*;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	
    10	public class PricingTest {
    11	    @Test
    12	    public void testPeakSeasonJuly() {
    13	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 7, 10)));
    14	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 7, 1)));
    15	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 7, 31)));
    16	    }
    17	
    18	    @Test
    19	    public void testPeakSeasonDecember() {
    20	        assertFalse(Pricing.isPeakSeason(LocalDate.of(2027, 12, 14)));
    21	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 12, 15)));
    22	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 12, 31)));
    23	    }
    24	
    25	    @Test
    26	    public void testPeakSeasonJanuary() {
    27	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 1, 1)));
    28	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 1, 31)));
    29	    }
    30	
    31	    @Test
    32	    public void testPeakSeasonFebruary() {
    33	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 2, 1)));
    34	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 2, 28)));
    35	    }
    36	
    37	    @Test
    38	    public void testNightlyRateInPeakSeason() {
    39	        BigDecimal baseRate = new BigDecimal("249.90");
    40	        LocalDate peakDate = LocalDate.of(2027, 7, 10);
    41	        BigDecimal rate = Pricing.calculateNightlyRate(baseRate, peakDate);
    42	        assertEquals(new BigDecimal("299.88"), rate);
    43	    }
    44	
    45	    @Test
    46	    public void testNightlyRateOutOfPeakSeason() {
    47	        BigDecimal baseRate = new BigDecimal("249.90");
    48	        LocalDate lowDate = LocalDate.of(2027, 5, 10);
    49	        BigDecimal rate = Pricing.calculateNightlyRate(baseRate, lowDate);
    50	        assertEquals(new BigDecimal("249.90"), rate);
    51	    }
    52	
    53	    @Test
    54	    public void testDiscount() {
    55	        BigDecimal subtotal = new BigDecimal("599.76");
    56	        BigDecimal discount = Pricing.calculateDiscount(subtotal, "NON_REFUNDABLE");
    57	        assertEquals(new BigDecimal("89.96"), discount);
    58	    }
    59	
    60	    @Test
    61	    public void testNoDiscountForStandard() {
    62	        BigDecimal subtotal = new BigDecimal("599.76");
    63	        BigDecimal discount = Pricing.calculateDiscount(subtotal, "STANDARD");
    64	        assertEquals(0, discount.compareTo(BigDecimal.ZERO));
    65	    }
    66	
    67	    @Test
    68	    public void testTotal() {
    69	        BigDecimal subtotal = new BigDecimal("599.76");
    70	        BigDecimal discount = new BigDecimal("89.96");
    71	        BigDecimal total = Pricing.calculateTotal(subtotal, discount);
    72	        assertEquals(new BigDecimal("509.80"), total);
    73	    }
    74	
    75	    @Test
    76	    public void testISS() {
    77	        BigDecimal total = new BigDecimal("779.80");
    78	        BigDecimal iss = Pricing.calculateIss(total);
    79	        assertEquals(new BigDecimal("38.99"), iss);
    80	    }
    81	}
